<script setup lang="ts">
import { computed, ref } from 'vue';import { useRoute } from 'vue-router';import type { ReplaySessionV2 } from '@smart-factory/domain';import { qualityLabel } from '@smart-factory/domain';import { useSiteStore } from '../stores/site';import PageHeader from '../components/PageHeader.vue';
const store=useSiteStore();const route=useRoute();const id=computed(()=>String(route.params.id??''));const session=ref<ReplaySessionV2|null>(null);const loading=ref(false);const error=ref('');
function sourceLabel(origin?:string){return origin==='REAL_DEVICE'?'真实采集':origin==='SIMULATION'?'内置数据源':'来源未知';}
async function create(){loading.value=true;error.value='';try{const to=Date.now(),from=to-10*60*1000;session.value=await store.createReplaySessionV2({instanceId:id.value,from,to});}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;}}
create();
</script>
<template><section class="operator-page replay-page"><PageHeader title="历史回放" eyebrow="历史记录" :back-to="`/applications/${id}`" back-label="返回监测" description="按时间顺序查看最近的监测数据和规则变化。"/><section class="replay-toolbar"><button class="btn-primary" :disabled="loading" @click="create">查看最近10分钟</button><span v-if="session">{{new Date(session.from).toLocaleTimeString('zh-CN',{hour12:false})}} — {{new Date(session.to).toLocaleTimeString('zh-CN',{hour12:false})}}</span><b v-if="session">规则变化 {{session.ruleTransitions?.length??0}} 项</b></section><div v-if="error" class="inline-alert" data-state="bad">{{error}}</div><section v-for="stream in session?.streams??[]" :key="stream.role" class="hmi-panel"><div class="hmi-panel-head"><div><span>监测记录</span><h2>{{stream.history.items[0]?.label??stream.pointId}}</h2></div><small>{{stream.history.items.length}} 条</small></div><div class="table-wrap"><table class="hmi-table"><thead><tr><th>时间</th><th>值</th><th>状态</th><th>来源</th></tr></thead><tbody><tr v-for="p in stream.history.items.slice(-80).reverse()" :key="`${p.sampleTs}:${p.seq}`"><td>{{new Date(p.sampleTs).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{p.value}} {{p.unit??''}}</td><td>{{qualityLabel[p.quality]??p.quality}}</td><td>{{sourceLabel(p.provenance?.originKind)}}</td></tr></tbody></table></div></section></section></template>
